        c[@"FlareDataGrid"] = new ApiComponentInfo(
            @"FlareDataGrid",
            @"Flare.Components.FlareDataGrid",
            @"Flare.Components",
            @"FlareDataGrid partial: column-band (grouped header) layout logic.",
            null,
            new ApiParameterInfo[]
            {
                new ApiParameterInfo(@"AdditionalAttributes", @"IReadOnlyDictionary<string, object>?", null, @"Additional attributes.", null, false, false, false, @"FlareComponentBase"),
                new ApiParameterInfo(@"Aggregates", @"IReadOnlyList<AggregateDefinition<TItem?>>?", null, @"Aggregate definitions rendered as a footer row (Sum/Count/Average/Min/Max per column).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Bordered", @"bool", null, @"Draws vertical borders between columns.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"CellSelection", @"bool", null, @"Enables Excel-like cell-range selection. With the grid focused, arrow keys move the active cell, Shift+Arrow (and Shift+Home/End) extend a rectangular selection, click-drag and Shift+Click select with the mouse, Ctrl+C copies the selection to the clipboard as tab-separated text and (when OnPaste is set) Ctrl+V pastes tab-separated text into the cells.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Class", @"string?", null, @"Additional CSS class(es) appended to the component's root element.", null, false, false, false, @"FlareComponentBase"),
                new ApiParameterInfo(@"ColumnDefinitions", @"IEnumerable<DataGridColumn<TItem?>>?", null, @"Columns supplied as data instead of markup - generated from metadata, kept in a field, shared between grids or reordered in C#. Combines with Columns: markup columns come first (their band structure fixes their header positions), then these, and a definition whose Key a markup column already uses is ignored.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"ColumnOrder", @"IReadOnlyList<string>?", null, @"Controlled column display order by column key - Id, else SortKey, else Title (left to right). Columns not listed keep their declared order at the end. When set, treat the grid as controlled and update this value from OnColumnOrderChanged.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Columns", @"RenderFragment?", null, @"FlareColumn descriptors defining the grid columns.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"ColumnsButtonLabel", @"string?", null, @"Overrides the label on the column-picker button (defaults to a localized ""Columns"").", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Context", @"DataGridContext<TItem?>?", null, @"An externally-owned handle for driving this grid. Declare a DataGridContext in the page and pass it here to put pagers, column pickers, query editors or any custom control anywhere in the layout, bound to this grid. When omitted the grid uses one of its own, which children reach through the cascade.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Dense", @"bool", null, @"Compact row height and cell padding for dense tables.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"EditMode", @"DataGridEditMode", null, @"Edit mode: None (default), Inline (row), or Cell (click individual cells).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"EmptyStateContent", @"RenderFragment?", null, @"Custom content displayed when no data rows are available. Defaults to FlareEmptyState.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"FillHeight", @"bool", null, @"Makes the component spend the height it was given rather than growing to fit its content, and pass that height on to its children. This is the screen-fit case - a grid under a filter bar, a chart beside a table, a page that fills the window instead of scrolling with it. It needs an ancestor with a height of its own, and EVERY link between that ancestor and this component needs the same switch: one link left at auto collapses the chain back to content height, silently. A page gets its first definite height from FlareLayoutContent FillHeight; anywhere else - a demo, a dialog - give the outermost box one explicitly. The box that SUPPLIES a height does not fill: when Style declares a height of its own, that height wins and this switch is ignored, because the two are contradictory instructions and the written number is the one you can see in the markup.", null, false, false, false, @"FlareContainerBase"),
                new ApiParameterInfo(@"FilterMode", @"DataGridFilterMode", null, @"Controls how column filters are displayed: Simple (text inputs), Menu (dropdowns), or Both.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"FilterPlaceholder", @"string?", null, @"Overrides the placeholder text shown in filter inputs.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"FooterContent", @"RenderFragment?", null, @"Custom content rendered in the footer area below the table (the toolbar's counterpart at the bottom). Like ToolbarContent, child components placed here resolve the grid automatically via the cascade. Use it to position grid controls (e.g. a FlareDataGridPager) below the data.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Grouping", @"RenderFragment?", null, @"Grouping levels, declared as nested DataGridGroup child components (outermost first). When present, rows are grouped into nested, collapsible sections with optional per-level or grid-level aggregates. The level keys also flow to a server provider via DataGridRequest.GroupKeys. <Grouping> <DataGridGroup Key=""Role"" Selector=""@(p => p.Role)"" /> <DataGridGroup Key=""City"" Selector=""@(p => p.City)"" /> </Grouping>", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Height", @"string?", null, @"How tall the whole component may be, as a CSS length - the toolbar, the pager and the footer are inside the budget, and the table container scrolls in what is left. Applies in EVERY mode, paged or not, virtualized or not; null, ""auto"" or ""none"" removes it and the grid grows with its rows so the page scrolls instead. Ignored when FillHeight is set. An absolute length is a CAP: a grid with fewer rows than that is as tall as its rows. A PERCENTAGE is a height rather than a cap, because a percentage cap against a content-sized parent computes to none; it needs an ancestor with a definite height, and falls back to content height where there is none. When the height is the layout's answer rather than a number the page can write down, FillHeight says so without a number.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"HiddenColumns", @"IReadOnlyCollection<string>?", null, @"Controlled set of hidden column keys. When set, the grid reflects this value and reports changes via HiddenColumnsChanged; otherwise the grid manages hiding internally.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"HiddenColumnsChanged", @"EventCallback<IReadOnlyCollection<string>>", null, @"Raised with the full set of hidden column keys whenever a column is shown or hidden.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Hoverable", @"bool", null, @"Highlights the row under the pointer on hover.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"InfiniteScroll", @"bool", null, @"Accumulates rows chunk by chunk as the user reaches the bottom, instead of paging. No pager is shown: this is a paging strategy of its own and it replaces PageSize's. It differs from Virtual in what it asks of the source, which is the whole reason both exist. A virtualized provider is asked for an arbitrary window - ""rows 4000 to 4050"" - and has to report a total, because the scrollbar cannot be sized without one. This one walks sequentially from the first chunk and learns where the end is by getting a short one, so it works against a source that can neither seek nor count: a cursor- or keyset-paginated API, a search endpoint, anything whose COUNT is too expensive to run per keystroke. Where the source can do both, Virtual is the better answer - it gives a real scrollbar and does not grow without bound. The chunk size is PageSize, or 50 when that is 0 (which means ""do not page"" and is no answer to ""how much to fetch""). Loading stops when a chunk comes back shorter than the chunk size, or when the reported total is reached. Combine with Virtual to recycle what has accumulated - otherwise a long enough scroll ends with the whole set in the DOM.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Items", @"IEnumerable<TItem?>?", null, @"In-memory data source bound to the grid.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"ItemsProvider", @"Func<DataGridRequest, Task<DataGridResult<TItem?>>>?", null, @"Server-side data provider for paging and sorting.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"LoadingIndicator", @"DataGridLoadingIndicator", null, @"How the loading state is shown: a circular ring (default), skeleton rows, or text only.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"LoadingText", @"string?", null, @"Overrides the loading indicator text.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnBatchCancel", @"EventCallback", null, @"Callback raised when batch edit is cancelled.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnBatchSave", @"EventCallback<IReadOnlyDictionary<TItem?, IReadOnlyDictionary<string, string>>>", null, @"Callback raised when batch save is requested. The parameter contains all edited items with their edit values.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnColumnOrderChanged", @"EventCallback<IReadOnlyList<string>>", null, @"Raised after the user reorders columns, with the new left-to-right order (column keys).", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnFilterChanged", @"EventCallback<IReadOnlyList<DataGridFilter>>", null, @"Raised when a column filter changes, with the full structured filter model.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnGroupChanged", @"EventCallback<IReadOnlyList<string>>", null, @"Raised when the group-by keys change (outermost first).", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnPageChanged", @"EventCallback<int>", null, @"Raised when the current page index changes.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnPaste", @"EventCallback<DataGridPaste<TItem?>>", null, @"Raised on Ctrl+V when CellSelection is enabled: the clipboard's tab-separated text is parsed and mapped onto the cells starting at the top-left of the current selection. The handler applies each cell's value to its row item (the grid cannot write through the read-only column accessors itself).", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnRowCancelled", @"EventCallback<TItem?>", null, @"Callback fired when a single row edit is cancelled.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnRowReordered", @"EventCallback<DataGridRowReorder<TItem?>>", null, @"Raised after the user drags a row onto another row, with the dragged item, the drop target, and their indices within the current page.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnRowSaved", @"EventCallback<TItem?>", null, @"Callback fired when a single row is saved (inline edit).", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnSortChanged", @"EventCallback<IReadOnlyList<DataGridSort>>", null, @"Raised when the sort changes, with all active sorts in apply order.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OnStateChanged", @"EventCallback<DataGridState>", null, @"Raised after any sort/filter/group/page/page-size change, with the complete grid state.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"OverscanCount", @"int?", null, @"Number of extra rows to render above/below the visible area (also fetched for ItemsProvider). null (default): use 20 - pre-loads 20 rows in each direction for smooth scrolling.> 0: custom overscan count for fine-tuning.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"PageSize", @"int", null, @"Number of rows on a page, or 0 (the default) for no paging at all: every row goes into one page and the grid scrolls inside whatever height it was given. Paging and scrolling are independent - a paged grid still scrolls when its page is taller than Height. Composes with Virtual: a virtualized grid recycles the rows of its current page. InfiniteScroll is the exception - loading the next page on scroll IS a paging strategy, so it replaces the pager. With an ItemsProvider or Queryable, 0 means one request for the whole set unless Virtual is on, which fetches a window at a time. That is what ""no paging"" has to mean against a remote source, so set a page size, Virtual or InfiniteScroll when the source is large.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"PersistStateKey", @"string?", null, @"When set, the grid persists sort/filter/column state to localStorage under this key. State is restored on component init and saved on every user change.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"PinnedBottomRows", @"IReadOnlyList<TItem?>?", null, @"Rows pinned to the bottom of the grid - always shown below the scrolling data, outside sorting, filtering and paging. Sticky in scrolling grids (above any aggregate row).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"PinnedTopRows", @"IReadOnlyList<TItem?>?", null, @"Rows pinned to the top of the grid - always shown above the scrolling data, outside sorting, filtering and paging (e.g. a totals or highlighted row). Sticky in scrolling grids.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Queryable", @"IQueryable<TItem?>?", null, @"A queryable data source (e.g. an EF Core DbSet). When set, the grid translates its sort/filter/paging into a LINQ expression tree via DataGridQuery and runs it against this query - so the database does the work, with no hand-written ItemsProvider. An explicit ItemsProvider takes precedence. Executes synchronously; for async EF execution supply an ItemsProvider instead.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"QuickFilter", @"Func<TItem?, bool>?", null, @"Optional predicate applied to every row after column filters; rows returning false are hidden.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"ReorderableColumns", @"bool", null, @"Enables drag-and-drop reordering of columns by dragging their headers.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowClassFunc", @"Func<TItem?, string>?", null, @"Returns extra CSS class string(s) for each data row, given the row item. Use for row-level conditional formatting (e.g. highlight rows by status).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowClick", @"EventCallback<TItem?>", null, @"Callback fired when a row is clicked.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowDetailTemplate", @"RenderFragment<TItem?>?", null, @"Template rendered as an expandable detail row below each data row.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowKey", @"Func<TItem?, object>?", null, @"Stable identity selector for each row, used as the render key (improves diffing, selection and virtualization). Defaults to the item reference when not set.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowReorderable", @"bool", null, @"Enables drag-and-drop reordering of rows. Reordering raises OnRowReordered; the owner updates the backing data (the grid does not mutate Items).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowStyleFunc", @"Func<TItem?, string>?", null, @"Returns an inline style string for each data row, given the row item.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowsLabel", @"string?", null, @"Overrides the rows-per-page label shown next to the page size selector.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"RowsPerPageOptions", @"IReadOnlyList<int>", null, @"Available page-size choices rendered in the pagination row-count selector. When empty the selector is hidden.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"SelectedItems", @"HashSet<TItem?>?", null, @"Currently selected items for two-way binding.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"SelectedItemsChanged", @"EventCallback<HashSet<TItem?>>", null, @"Callback fired when the selected items set changes.", null, false, true, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"SelectionMode", @"SelectionMode", null, @"Row selection mode - none, single, or multiple.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"ShowColumnPicker", @"bool", null, @"Shows a built-in ""Columns"" button in the toolbar that opens a checklist to show/hide individual columns. Hidden columns are tracked by their key (Id / SortKey / Title).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"ShowPager", @"bool", null, @"Whether the grid renders its own built-in pager below the table (default true). Set to false to suppress it and place a FlareDataGridPager yourself (e.g. in FooterContent or ToolbarContent).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"StickyHeader", @"bool", null, @"Keeps the header group - band rows, column titles and the filter row - pinned to the top of the table container while the rows scroll under it. Default true. Turn it off for a tall multi-row header that would eat the visible area, or for a print-shaped view where the header should scroll away with its rows. Has no visible effect on a grid with no height of its own, which does not scroll on its own to begin with. Pinned rows (PinnedTopRows, PinnedBottomRows) and the aggregate footer are separate promises and are not affected.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Striped", @"bool", null, @"Alternating row background (""zebra"" striping).", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Style", @"string?", null, @"Inline style string appended to the component's root element.", null, false, false, false, @"FlareComponentBase"),
                new ApiParameterInfo(@"ToolbarContent", @"RenderFragment?", null, @"Custom content rendered in the toolbar area above the table. Child components placed here (quick filter, presets, export, filter builder, column picker, pager) resolve the grid automatically via the cascade - no Grid binding needed.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Tree", @"DataGridTreeConfig<TItem?>?", null, @"Tree-grid configuration for hierarchical data. When set, enables expand/collapse UI and recursive row rendering based on the ChildrenSelector.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"Virtual", @"bool?", null, @"Recycles rows: only the visible window plus an overscan margin lives in the DOM. It decides nothing else - paging, grouping, the tree, detail rows, row reorder and cell selection all behave exactly as they do without it, and a paged grid recycles the rows of its current page. null (the default) lets the grid decide: it recycles an in-memory source of more than 500 rows when it has a height to scroll in (Height or FillHeight). Set it explicitly to true or false to take the decision yourself - false is the answer when every row must be in the DOM for the browser's own find or for printing. With an ItemsProvider the choice is always yours, since the grid would have to fetch the whole set once to find out how big it is; combine the two to load rows on demand as the user scrolls.", null, false, false, false, @"FlareDataGrid"),
                new ApiParameterInfo(@"VirtualItemSize", @"float?", null, @"Estimated row height in pixels for the virtual scroller. null (default): auto-detect via ResizeObserver - works for variable-height rows.> 0: fixed height - faster rendering, use when all rows have the same height (e.g. 44px for compact tables).", null, false, false, false, @"FlareDataGrid"),
            },
