                new ApiParameterInfo(@"RefusedTargets", @"Func<TPayload?, IEnumerable<string>>?", null, @"Zones that must not take the payload, named by id, asked once per drag. This is the answer for a component that declares its zones as markup rather than as FlareDropZone components: the context has no list of those to run CanDrop over, so it takes a refusal instead. A tree refusing its own subtree is the case this exists for - the branches inside a dragged node belong to it, and a drop there detaches the whole branch from the tree.", null, false, false, false, @"FlareDragContext"),
